<?php
namespace Tests\Feature;
use App\Livewire\Admin\Inbox\Index;use App\Models\{DepositRequest,InvestmentAccount,Investor,InvestorWallet,SupportTicket,User,WithdrawalRequest};use App\Services\SupportTicketService;use Illuminate\Foundation\Testing\RefreshDatabase;use Livewire\Livewire;use Tests\TestCase;
class AdminInboxTest extends TestCase{use RefreshDatabase;public function test_unified_queue_counts_order_links_details_and_badge():void{$admin=User::factory()->create(['role'=>'admin','is_active'=>true]);[$i,$u,$a]=$this->context();$normal=app(SupportTicketService::class)->create($i,$u,'general','Обычный вопрос','Текст');$high=app(SupportTicketService::class)->create($i,$u,'technical','Важный вопрос','Текст','high');WithdrawalRequest::create(['investor_id'=>$i->id,'investment_account_id'=>$a->id,'type'=>'dividend','requested_amount'=>'10','reserved_amount'=>'10','currency'=>'USDT','status'=>'review','requested_at'=>now()]);DepositRequest::create(['investor_id'=>$i->id,'investment_account_id'=>$a->id,'requested_amount'=>'20','currency'=>'USDT','status'=>'submitted','requested_at'=>now()]);InvestorWallet::create(['investor_id'=>$i->id,'currency'=>'USDT','network'=>'TRC20','address'=>'TInboxWallet001','status'=>'pending']);$this->actingAs($admin)->get('/admin/inbox')->assertOk()->assertSee('Financial Operations Center')->assertSee('Вывод дивидендов')->assertSee('Пополнение')->assertSee('Новый кошелёк')->assertSee('Важный вопрос');Livewire::actingAs($admin)->test(Index::class)->assertViewHas('kpis',fn($k)=>$k['attention']===5)->assertViewHas('items',fn($items)=>$items[0]['title']==='Важный вопрос')->set('sort','oldest')->call('openTicket',$normal->id)->assertSee('Ответ инвестору')->assertSee('Внутренняя заметка');$this->actingAs($admin)->get('/admin')->assertSee('Обращения');}
public function test_deposit_lifecycle_labels_and_active_queue_scope():void{$admin=User::factory()->create(['role'=>'admin','is_active'=>true]);[$i,,$a]=$this->context();$pending=DepositRequest::create(['investor_id'=>$i->id,'investment_account_id'=>$a->id,'requested_amount'=>'10','currency'=>'USDT','status'=>'pending','requested_at'=>now()]);$submitted=DepositRequest::create(['investor_id'=>$i->id,'investment_account_id'=>$a->id,'requested_amount'=>'20','currency'=>'USDT','status'=>'submitted','requested_at'=>now()->subMinute()]);foreach(['rejected','cancelled','confirmed'] as $status)DepositRequest::create(['investor_id'=>$i->id,'investment_account_id'=>$a->id,'requested_amount'=>'30','currency'=>'USDT','status'=>$status,'requested_at'=>now()->subMinutes(2)]);Livewire::actingAs($admin)->test(Index::class)->assertViewHas('kpis',fn($k)=>$k['financial']===2)->assertViewHas('items',fn($items)=>collect($items)->contains(fn($x)=>$x['source_id']===$pending->id&&$x['status']==='Новая'&&$x['action']==='Открыть')&&collect($items)->contains(fn($x)=>$x['source_id']===$submitted->id&&$x['status']==='Проверка'&&$x['action']==='Открыть')&&count($items)===2);}
public function test_investor_cannot_open_admin_inbox():void{[, $user]=$this->context();$this->actingAs($user)->get('/admin/inbox')->assertForbidden();}
private function context():array{$u=User::factory()->create(['role'=>'investor','is_active'=>true]);$i=Investor::create(['user_id'=>$u->id,'code'=>'INBOX','status'=>'active']);$a=InvestmentAccount::create(['investor_id'=>$i->id,'currency'=>'USDT','status'=>'active']);return[$i,$u,$a];}}
